<script>
  import VehicleSvm from './VehicleSvm.svelte';
  import { onDestroy } from 'svelte';
  import { device, nameOf, value, num, note, home } from '../lib/home.svelte.js';
  import { asHuman, CANCELLED } from '../lib/auto.svelte.js';
  import { t } from '../../lib/i18n.svelte.js';
  let { id, name = null } = $props();
  const d = $derived(device(id));
  const read = (key) => value(id, key);
  function object(v, fallback = null) { try { return typeof v === 'string' ? JSON.parse(v) : v ?? fallback; } catch { return fallback; } }
  const readCaps = $derived(object(read('read_capabilities'), []));
  const caps = $derived(object(read('capabilities'), []));
  const ready = $derived(d?.online !== false && read('quality') === 'cached_recent' && typeof read('vehicle_at') === 'number' && home.now - read('vehicle_at') <= (read('max_age_seconds') ?? 3600) * 1000);
  let opened = $state(false), tab = $state('readings'), action = $state(null), form = $state({}), confirmed = $state(false), busy = $state(false), error = $state(''), report = $state(null), privateView = $state(null), destination = $state({});
  let from = $state(new Date(Date.now() - 29 * 86400000).toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' }));
  let to = $state(new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' }));
  const initialDay = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' });
  let receipt = $state(false), financial = $state({ day: initialDay, kind: 'home', source: 'invoice', measured: true, tariff_from: initialDay });
  const label = (key) => t(`vehicle.${key}`);
  const fmt = (v, unit = '') => v == null ? label('unknown') : typeof v === 'number' ? `${num(v, unit === '€' || unit === '€/100 km' ? 2 : 1)} ${unit}` : typeof v === 'boolean' ? t(v ? 'commun.oui' : 'commun.non') : String(v);
  const time = (at) => typeof at === 'number' ? new Date(at).toLocaleString(undefined, { timeZone: 'Europe/Paris' }) : label('unknown');
  onDestroy(() => { privateView = null; globalThis.MoliVehicleExport?.privacy(false); });
  $effect(() => { globalThis.MoliVehicleExport?.privacy(privateView != null || action?.key === 'set_navigation'); });
  async function request(path, method = 'GET', body = null) { const r = await fetch(`/api/vehicles/${encodeURIComponent(id)}/${path}`, { method, headers: { 'content-type': 'application/json', 'x-moli-origin': 'ui' }, ...(body == null ? {} : { body: JSON.stringify(body) }), cache: 'no-store' }); const v = await r.json(); if (!r.ok) { const e = new Error(v.error || label('failed')); e.status = r.status; throw e; } return v; }
  async function guarded(work) { busy = true; error = ''; try { await asHuman(nameOf(id, name), work); } catch (e) { if (e.message !== CANCELLED) error = e.message; } finally { busy = false; } }
  function choose(cap) { action = cap; form = {}; destination = {}; confirmed = !['lock','unlock','set_windows','start_hazard_lights','start_hazard_lights_and_horn','force_refresh','set_navigation','open_charge_port','close_charge_port','start_valet_mode','stop_valet_mode'].includes(cap.key); for (const [key, spec] of Object.entries(cap.parameters)) { if (spec.type === 'boolean') form[key] = false; } }
  async function send(event) {
    event.preventDefault(); if (!action || !confirmed || (!ready && action.key !== 'refresh_cached')) return;
    const chosen = action; const params = {};
    try { for (const [key, spec] of Object.entries(chosen.parameters)) { const v = form[key]; if (v == null || v === '') continue; params[key] = spec.type === 'days' ? v.split(',').map((v) => Number(v.trim())) : spec.type === 'boolean' || spec.type === 'time' || key === 'preset' ? v : Number(v); } } catch { error = label('failed'); return; }
    await guarded(async () => { if (chosen.key === 'set_navigation') { const staged = await request('private/navigation', 'POST', { latitude: Number(destination.latitude), longitude: Number(destination.longitude), name: destination.name || '', consent: true }); params.navigation_token = staged.navigation_token; destination = {}; } const res = await fetch('/api/command', { method: 'POST', headers: { 'content-type': 'application/json', 'x-moli-origin': 'ui' }, body: JSON.stringify({ point: `${id}/${chosen.key}`, value: JSON.stringify(params) }) }); if (!res.ok || res.status === 202) { const v = await res.json(); const e = new Error(v.error || v.reason || label('failed')); e.status = res.status; throw e; } note(label('ack')); action = null; });
  }
  async function journal() { await guarded(async () => { report = await request(`journal?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`); }); }
  async function showPrivate(field) { await guarded(async () => { privateView = await request(`private/${field}`); }); }
  function download() { if (!report) return; if (globalThis.MoliVehicleExport?.save) { globalThis.MoliVehicleExport.save(JSON.stringify(report)); return; } const url = URL.createObjectURL(new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = `moli-vehicle-${from}-${to}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
  function editReceipt(row) { financial = Object.fromEntries(['id','day','kind','source','measured','tariff_from','grid_kwh','hp_kwh','hc_kwh','hp_eur_kwh','hc_eur_kwh','paid_eur','driving_price_eur_kwh'].map((k)=>[k,row[k]])); const local=(ms)=>{const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}; financial.from_time=local(row.from_ms);financial.to_time=local(row.to_ms);receipt=true; }
  async function saveReceipt(event) { event.preventDefault(); await guarded(async () => { const { from_time, to_time, ...fields } = financial; const row = { ...fields, id: financial.id || crypto.randomUUID(), from_ms: new Date(financial.from_time).getTime(), to_ms: new Date(financial.to_time).getTime() }; for (const k of ['grid_kwh', 'hp_kwh', 'hc_kwh', 'hp_eur_kwh', 'hc_eur_kwh', 'paid_eur', 'driving_price_eur_kwh']) row[k] = financial[k] === '' || financial[k] == null ? null : Number(financial[k]); row.measured = row.source !== 'owner_estimate'; await request('finance', 'POST', row); receipt = false; report = await request(`journal?from=${from}&to=${to}`); }); }
</script>

<section class="card vehicle" data-testid="vehicle-card">
  <div class="card-head"><h2>{nameOf(id, name)}</h2><span class="muted">Bluelink / myHyundai</span></div>
  <div class="headline"><div class="car" aria-hidden="true"><svg viewBox="0 0 320 110"><path d="M20 75 35 46 86 39 117 16H226L269 48 301 56 310 86H17Z" fill="currentColor" opacity=".18"/><path d="m94 42 29-21h93l30 25Z" fill="currentColor" opacity=".35"/><circle cx="73" cy="84" r="21" fill="currentColor"/><circle cx="259" cy="84" r="21" fill="currentColor"/><path d="M108 76H222" stroke="currentColor" stroke-width="11"/></svg></div><strong>{fmt(read('soc'), '%')}</strong><span>{fmt(read('ev_range_km'), 'km')}</span></div>
  <p class:warning={!ready}>{label(ready ? 'cached' : 'stale')} · {time(read('vehicle_at'))}</p>
  <button class="ghost" onclick={() => { opened = !opened; if (!opened) { privateView = null; action = null; destination = {}; } }} aria-expanded={opened}>{label(opened ? 'close' : 'details')}</button>
  {#if opened}
    <nav aria-label={label('details')}>{#each ['readings', 'commands', 'journal'] as key}<button class:active={tab === key} onclick={() => { tab = key; privateView = null; if (action?.key === 'set_navigation') { action = null; destination = {}; } }}>{label(key)}</button>{/each}</nav>
    {#if error}<p role="alert" class="warning">{error}</p>{/if}
    {#if tab === 'readings'}
      <dl class="summary">{#each [['soc','%'],['soh','%'],['battery_12v','%'],['odometer','km'],['charging_power','kW'],['charging',''],['ev_range_km','km'],['air_temperature_c','°C'],['outside_temperature_c','°C'],['is_locked','']] as [key,unit]}<div><dt>{label(key)}</dt><dd>{fmt(read(key),unit)}</dd></div>{/each}</dl>
      <p>{label('vehicle_at')}: {time(read('vehicle_at'))}<br/>{label('cloud_at')}: {time(read('cloud_at'))}<br/>{label('received_at')}: {time(read('received_at'))}</p>
      <button disabled={busy || read('location_enabled') !== true} onclick={() => showPrivate('gps')}>{label('gps')}</button><button disabled={busy || read('api_mode') === 'europe'} onclick={() => showPrivate('svm')}>{label('svm')}</button>{#if read('api_mode') === 'europe'}<p class="muted">{label('legacy_svm_unavailable')}</p>{/if}
      {#if privateView}<div class="private">{#if privateView.base64}<VehicleSvm view={privateView} />{:else}<p>{label('gps')}: {fmt(privateView.latitude)} / {fmt(privateView.longitude)} · {time(privateView.location_at)}</p>{/if}<p>{label('private')}</p><button onclick={() => privateView = null}>{t('commun.fermer')}</button></div>{/if}
      <details><summary>{label('read_coverage')}</summary>{#each readCaps as cap}<p>{cap.ha} · {label(cap.reason)}{#if cap.points.length} · {cap.points.join(', ')}{/if}</p>{/each}</details>
      <details><summary>{label('all_readings')}</summary><dl>{#each d?.points.filter((p) => p.access.read && !['capabilities','read_capabilities'].includes(p.key)) ?? [] as p (p.key)}<div><dt>{p.label}</dt><dd>{fmt(read(p.key), p.unit || '')}</dd></div>{/each}</dl></details>
    {:else if tab === 'commands'}
      <p>{label('command_help')}</p>
      <div class="controls">{#each caps.filter((c) => c.available) as cap}<button disabled={busy || (!ready && cap.key !== 'refresh_cached')} onclick={() => choose(cap)}>{label(cap.key)}</button>{/each}</div>
      {#if action}<form onsubmit={send} autocomplete="off"><h3>{label(action.key)}</h3>{#if action.key === 'set_navigation'}<p>{label('navigation_privacy')}</p><div class="parameters"><label>{label('latitude')}<input type="number" min="-90" max="90" step="any" required bind:value={destination.latitude} /></label><label>{label('longitude')}<input type="number" min="-180" max="180" step="any" required bind:value={destination.longitude} /></label><label>{label('destination_name')}<input maxlength="80" bind:value={destination.name} /></label></div>{/if}<div class="parameters">{#each Object.entries(action.parameters).filter(([,spec]) => spec.type !== 'private_navigation') as [key,spec]}<label>{label(key)}{#if spec.type === 'boolean'}<input type="checkbox" bind:checked={form[key]} />{:else if spec.options}<select bind:value={form[key]} required><option value="">{label('choose')}</option>{#each spec.options as opt}<option value={opt}>{opt}</option>{/each}</select>{:else}<input type={spec.type === 'time' ? 'time' : spec.type === 'days' ? 'text' : 'number'} min={spec.min} max={spec.max} step={spec.step ?? 1} placeholder={spec.type === 'days' ? label('days_hint') : `${spec.min ?? ''}–${spec.max ?? ''}`} bind:value={form[key]} />{/if}</label>{/each}</div>{#if ['lock','unlock','set_windows','start_hazard_lights','start_hazard_lights_and_horn','force_refresh','set_navigation','open_charge_port','close_charge_port','start_valet_mode','stop_valet_mode'].includes(action.key)}<label class="confirmation"><input type="checkbox" bind:checked={confirmed} required />{label('confirm')}</label>{/if}<button type="submit" disabled={!confirmed || busy || (!ready && action.key !== 'refresh_cached')}>{label('send')}</button><button type="button" onclick={() => action = null}>{t('commun.annuler')}</button></form>{/if}
      <p>{label('last_command')}: {fmt(read('command_status'))}</p><button disabled={busy} onclick={() => showPrivate('action')}>{label('check_action')}</button>{#if privateView?.cloud_state}<p>{label('cloud_action')}: {privateView.cloud_state} · {label('ack')}</p>{/if}
      <details><summary>{label('unavailable')}</summary>{#each caps.filter((c) => !c.available) as cap}<p>{label(cap.key)} · {label(cap.reason)}</p>{/each}</details>
    {:else}
      <p>{label('journal_help')}</p><p class="muted">{label('provider_day_note')}</p><div class="dates"><label>{label('from')}<input type="date" bind:value={from} /></label><label>{label('to')}<input type="date" bind:value={to} /></label><button disabled={busy} onclick={journal}>{label('load')}</button><button disabled={!report || busy} onclick={download}>{label('export')}</button><button onclick={() => receipt = !receipt}>{label('receipt')}</button></div>
      {#if receipt}<form onsubmit={saveReceipt}><h3>{label('receipt')}</h3><p>{label('finance_help')}</p><div class="parameters"><label>{label('charge_from')}<input type="datetime-local" bind:value={financial.from_time} required /></label><label>{label('charge_to')}<input type="datetime-local" bind:value={financial.to_time} required /></label><label>{label('day')}<input type="date" bind:value={financial.day} required /></label><label>{label('tariff_from')}<input type="date" bind:value={financial.tariff_from} required /></label><label>{label('kind')}<select bind:value={financial.kind}><option value="home">{label('home')}</option><option value="external">{label('external')}</option></select></label><label>{label('source')}<select bind:value={financial.source}>{#each ['invoice','dedicated_meter','owner_estimate'] as source}<option value={source}>{label(source)}</option>{/each}</select></label>{#each ['grid_kwh','hp_kwh','hc_kwh','hp_eur_kwh','hc_eur_kwh','paid_eur','driving_price_eur_kwh'] as key}<label>{label(key)}<input type="number" min="0" step="0.001" bind:value={financial[key]} /></label>{/each}</div><button type="submit" disabled={busy}>{t('commun.valider')}</button></form>{/if}
      {#if report}<div class="journal-table"><table><thead><tr>{#each ['day','distance','consumed','regenerated','per100','grid','cost','estimated_cost','estimated_per100','weather','quality'] as key}<th>{label(key)}</th>{/each}</tr></thead><tbody>{#each report.days as day}<tr><th>{day.day}</th><td>{fmt(day.provider?.distance_km,'km')}</td><td>{fmt(day.provider?.consumed_wh == null ? null : day.provider.consumed_wh/1000,'kWh')}</td><td>{fmt(day.provider?.regenerated_wh == null ? null : day.provider.regenerated_wh/1000,'kWh')}</td><td>{fmt(day.kwh_per_100km,'kWh/100 km')}</td><td>{day.charges.map((c) => fmt(c.grid_kwh,'kWh')).join(' · ') || label('unknown')}</td><td>{day.charges.map((c) => `${fmt(c.cost_eur,'€')} (${label(c.quality)})`).join(' · ') || label('unknown')}</td><td>{fmt(day.estimated_driving_cost_eur,'€')}</td><td>{fmt(day.estimated_driving_eur_100km,'€/100 km')}</td><td>{fmt(day.weather?.mean_celsius,'°C')}</td><td>{label(day.status)}{#each day.charges as charge}<button onclick={() => editReceipt(charge)}>{label('edit_receipt')}</button>{/each}</td></tr>{/each}</tbody></table></div>{#each report.days.filter((d)=>d.provider || d.weather || d.charges.length) as day}<details><summary>{day.day} · {label('sources')}</summary><dl>{#each ['motor_wh','climate_wh','electronics_wh','battery_management_wh'] as key}<div><dt>{label(key)}</dt><dd>{fmt(day.provider?.[key] == null ? null : day.provider[key]/1000,'kWh')}</dd></div>{/each}</dl>{#if day.weather}<p>{label('weather_samples')}: {day.weather.count} · {fmt(day.weather.min_celsius,'°C')} / {fmt(day.weather.max_celsius,'°C')} · {time(day.weather.first)} → {time(day.weather.last)} · {day.weather.source_point}</p>{/if}{#each day.charges as charge}<p>{label(charge.source)} · {label(charge.kind)} · {time(charge.from_ms)} → {time(charge.to_ms)} · {fmt(charge.cost_eur,'€')} · {label(charge.quality)}</p>{/each}</details>{/each}<h3>{label('between')}</h3>{#each [...(report.current_charge ? [report.current_charge] : []),...(report.current_interval ? [report.current_interval] : []),...report.intervals] as interval}<p>{label(interval.kind)} · {time(interval.from)} → {time(interval.to)} · {fmt(interval.distance_km,'km')} · {fmt(interval.consumed_wh == null ? null : interval.consumed_wh/1000,'kWh')} · {fmt(interval.grid_kwh,'kWh')} · {fmt(interval.estimated_driving_cost_eur,'€')} ({label('estimated')}) · {label(interval.quality)}</p>{/each}<p>{label('cost_unknown')}</p>{/if}
    {/if}
  {/if}
</section>
<style>
  .headline{display:flex;gap:18px;align-items:center;flex-wrap:wrap}.headline strong{font-size:2rem}.car{width:200px;color:var(--accent,var(--ink-2))}nav,.controls,.dates{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button{min-height:48px;border:1px solid var(--line);border-radius:12px;padding:10px 16px;background:var(--card,#fff);color:var(--ink);font:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:hover:not(:disabled){background:var(--bg,#f2f4f7)}button:focus-visible{outline:3px solid var(--accent,#dcad21);outline-offset:2px}nav .active{font-weight:750;border-bottom:2px solid currentColor}.summary,.parameters{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px}dd{margin:4px 0 12px;overflow-wrap:anywhere}dt{color:var(--ink-3);font-size:.85rem}.warning{color:var(--warn,#ad5900)}label{display:flex;flex-direction:column;gap:6px}input,select{min-height:44px;max-width:100%;padding:6px}label.confirmation{flex-direction:row;align-items:center;margin:20px 0}form{padding:16px;border:1px solid var(--line);border-radius:12px;margin:12px 0}.journal-table{overflow:auto;max-height:480px}table{border-collapse:collapse;white-space:nowrap}td,th{padding:10px;border-bottom:1px solid var(--line);text-align:left}.private{padding:12px;border:1px solid var(--line)}details{margin:16px 0}summary{cursor:pointer;padding:12px}
</style>
